from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyBullishCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.fast_period = 5
        self.slow_period = 20

        # Can be overridden with the QC parameter "ProfitTargetPercent".
        self.profit_target = (
            float(self.GetParameter("ProfitTargetPercent") or "20.0") / 100.0
        )

        self.closes = []
        self.current_bucket = None
        self.bucket_bars = []

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.no_entry_date = None

    def OnData(self, data: Slice):
        current_date = self.Time.date()

        self._liquidate_unexpected_spy_position()

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            # Never intentionally hold through expiration.
            if current_date >= expiry_date:
                self.no_entry_date = current_date
                self._submit_exit("expiration processing")
            else:
                previous_trading_day = self._previous_trading_day(expiry_date)

                if (
                    current_date == previous_trading_day
                    and self.Time.time() >= time(15, 45)
                ):
                    self._submit_exit("expiration time stop")

                self._check_profit_target(data)

        bar = data.Bars.get(self.spy_symbol)
        if bar is None:
            return

        bar_time = bar.Time
        if bar_time.date() != current_date:
            return

        # Regular-session minute bars only.
        if not (time(9, 30) <= bar_time.time() < time(16, 0)):
            return

        bucket_start_minute = (
            ((bar_time.hour * 60 + bar_time.minute - 570) // 5) * 5 + 570
        )
        bucket_start = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            bucket_start_minute // 60,
            bucket_start_minute % 60,
        )

        if self.current_bucket is None:
            self.current_bucket = bucket_start

        if bucket_start != self.current_bucket:
            self._process_completed_bucket(data)
            self.current_bucket = bucket_start
            self.bucket_bars = []

        self.bucket_bars.append(bar)

        # A five-minute bar is complete after its fifth minute.
        if len(self.bucket_bars) == 5:
            self._process_completed_bucket(data)
            self.current_bucket = None
            self.bucket_bars = []

    def _process_completed_bucket(self, data: Slice):
        if len(self.bucket_bars) != 5:
            # Missing minute data: discard the incomplete interval.
            self.bucket_bars = []
            return

        bar_end = self.current_bucket + timedelta(minutes=5)
        bar_end_time = bar_end.time()

        close = self.bucket_bars[-1].Close

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(close)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        eligible_time = time(9, 45) <= bar_end_time <= time(14, 30)

        if not bullish_cross or not eligible_time:
            return

        if self.no_entry_date == self.Time.date():
            return

        if self._has_option_holding() or self._entry_order_is_open():
            return

        self._attempt_entry(data, close)

    def _attempt_entry(self, data: Slice, spy_price: float):
        chains = data.OptionChains

        if not chains:
            self.Debug("Skipped entry: current Slice has no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = []
        for chain in chains.values():
            contracts.extend(list(chain))

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies the seven-day rule.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at the selected expiration."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Submitted entry: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def _check_profit_target(self, data: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        quote = data.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target_price = self.entry_price * (1.0 + self.profit_target)

        if midpoint >= target_price:
            self._submit_exit("profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        for ticket in self.Transactions.GetOpenOrders(self.held_symbol):
            ticket.Cancel("Replacing with liquidation order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag="Exit: " + reason
        )

        self.Debug(
            "Submitted exit for {0}: {1}".format(self.held_symbol, reason)
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.entry_ticket = None

                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled,
            ):
                if order_event.Status != OrderStatus.PartiallyFilled:
                    self.entry_ticket = None

        if order_event.Symbol.SecurityType == SecurityType.Option:
            event_type = order_event.Type
            if event_type in (
                getattr(OrderEventType, "OptionExercise", None),
                getattr(OrderEventType, "OptionAssignment", None),
            ):
                self.Debug(
                    "Unexpected option exercise or assignment: {0}".format(
                        order_event.Symbol
                    )
                )
                self._liquidate_unexpected_spy_position()

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {0} at {1}".format(
                            order_event.Symbol,
                            order_event.FillPrice
                        )
                    )
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.exit_ticket = None

    def _liquidate_unexpected_spy_position(self):
        if self.Portfolio[self.spy_symbol].Invested:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.Liquidate(
                self.spy_symbol,
                tag="Unexpected exercise or assignment handling"
            )
            self.no_entry_date = self.Time.date()

    def _has_option_holding(self) -> bool:
        return any(
            security.Invested
            and security.Symbol.SecurityType == SecurityType.Option
            for security in self.Portfolio.Values
        )

    def _entry_order_is_open(self) -> bool:
        return (
            self.entry_ticket is not None
            and self._ticket_is_open(self.entry_ticket)
        )

    @staticmethod
    def _ticket_is_open(ticket) -> bool:
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted,
            OrderStatus.CancelPending,
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate
