from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SPYCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda u: u.IncludeWeeklys()
                        .Strikes(-1000, 1000)
                        .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.closes = []
        self.previous_fast = None
        self.previous_slow = None

        # No numeric target was specified; 1.50 means a 50% gain.
        self.profit_target_multiple = 1.50

        self.bucket_start = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_fill_price = None
        self.expiration_date = None
        self.time_stop_date = None

        self.current_day = None
        self.no_entry_today = False
        self.equity_liquidation_submitted = False

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.current_day != today:
            self.current_day = today
            self.no_entry_today = False
            self.equity_liquidation_submitted = False

        if self.expiration_date is not None and today >= self.expiration_date:
            self.no_entry_today = True
            if self._option_quantity() != 0 and self.exit_ticket is None:
                self._submit_option_exit("expiration-day liquidation")

        if self.Portfolio[self.spy].Quantity != 0:
            self.no_entry_today = True
            if not self.equity_liquidation_submitted:
                self.Debug(
                    "Unexpected SPY exercise or assignment; liquidating equity"
                )
                self.Liquidate(
                    self.spy,
                    "unexpected exercise or assignment"
                )
                self.equity_liquidation_submitted = True

        self._evaluate_exit(slice)

        bar = self._get_spy_bar(slice)
        if bar is not None:
            self._accept_minute_bar(bar)

    def _get_spy_bar(self, slice: Slice):
        try:
            if slice.Bars.ContainsKey(self.spy):
                return slice.Bars[self.spy]
        except Exception:
            try:
                return slice.Bars[self.spy]
            except Exception:
                pass
        return None

    def _accept_minute_bar(self, bar: TradeBar):
        local = bar.EndTime
        if local.tzinfo is not None:
            local = local.astimezone(self.TimeZone).replace(tzinfo=None)

        if (
            local.weekday() >= 5
            or local.time() < time(9, 30)
            or local.time() > time(16, 0)
        ):
            return

        minute = local.hour * 60 + local.minute
        end_minute = 30 + ((minute - 30 + 4) // 5) * 5
        start_minute = end_minute - 5
        start = datetime.combine(
            local.date(),
            time(start_minute // 60, start_minute % 60)
        )

        if self.bucket_start is not None and start != self.bucket_start:
            self._finish_bucket()
            self.bucket_bars = {}

        self.bucket_start = start
        self.bucket_bars[local.minute] = bar

        # Minute EndTimes 09:31..09:35 produce the bar ending at 09:35.
        if len(self.bucket_bars) == 5 and local.minute == end_minute % 60:
            self._finish_bucket()
            self.bucket_bars = {}
            self.bucket_start = None

    def _finish_bucket(self):
        if self.bucket_start is None or len(self.bucket_bars) != 5:
            return

        expected = set(
            range(self.bucket_start.minute + 1, self.bucket_start.minute + 6)
        )
        if set(self.bucket_bars.keys()) != expected:
            return

        bars = [
            self.bucket_bars[m]
            for m in sorted(self.bucket_bars.keys())
        ]

        self.closes.append(float(bars[-1].Close))
        if len(self.closes) > 20:
            self.closes.pop(0)

        if len(self.closes) < 20:
            return

        fast = sum(self.closes[-5:]) / 5.0
        slow = sum(self.closes[-20:]) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = self.bucket_start + timedelta(minutes=5)
        if (
            bullish
            and time(9, 45) <= bar_end.time() <= time(14, 30)
        ):
            self._try_entry()

    def _try_entry(self):
        if (
            self.no_entry_today
            or self.held_option is not None
            or self.entry_ticket is not None
        ):
