        self.Schedule.On(
            self.DateRules.EveryDay(self.spy),
            self.TimeRules.At(9, 30),
            self.ExpirationProcessing
        )

    def OnData(self, slice: Slice):
        self.current_slice = slice

        if self.Portfolio[self.spy].Invested:
            if not self.spy_liquidation_pending:
                quantity = self.Portfolio[self.spy].Quantity
                self.Debug(
                    "Unexpected SPY exercise or assignment; liquidating equity"
                )
                self.MarketOrder(self.spy, -quantity)
                self.spy_liquidation_pending = True
        else:
            self.spy_liquidation_pending = False

        self.UpdateTicketState()
        self.CheckProfitTarget(slice)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            # Manual update ensures the callback has access to this Slice.
            self.consolidator.Update(bar)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        end = bar.EndTime

        if end.time() < time(9, 35) or end.time() > time(16, 0):
            return

        if end.minute % 5 != 0 or end.second != 0:
            return

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(end, bar.Close)
        self.slow.Update(end, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if self.previous_fast is None or self.previous_slow is None:
            return

        bullish_crossover = (
            self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if (
            bullish_crossover
            and time(9, 45) <= end.time() <= time(14, 30)
        ):
            self.TryEntry()

    def TryEntry(self):
        today = self.Time.date()

        if self.no_entries_date == today:
            return

        if self.held_option is not None:
            return

        if (
            self.entry_ticket is not None
            and not self.entry_ticket.Status.IsClosed()
        ):
            return

        if self.current_slice is None:
            self.Debug("Skipped entry: no current Slice")
            return

        chain = self.current_slice.OptionChains.get(self.option)

        if chain is None:
            self.Debug("Skipped entry: no current option chain")
            return

        expiration_dates = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - today).days >= 7
        })

        if not expiration_dates:
            self.Debug(
                "Skipped entry: no expiration at least 7 calendar days away"
            )
            return

        selected_expiration = expiration_dates[0]
        spy_price = self.Securities[self.spy].Price

        candidates = [
            contract
            for contract in chain
            if (
                contract.Expiry.date() == selected_expiration
                and contract.Right == OptionRight.Call
                and contract.Strike >= 1.01 * spy_price
            )
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at selected expiration"
            )
            return

        contract = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug("Entry submitted: " + str(contract.Symbol))

    def CheckProfitTarget(self, slice: Slice):
        if self.held_option is None:
            return

        if self.entry_fill_price is None:
            return

        if not self.Portfolio[self.held_option].Invested:
            return

        quote = slice.QuoteBars.get(self.held_option)

        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= self.profit_target:
            self.SubmitExit("profit target")

    def TimeStop(self):
        if self.held_option is None:
            return

        expiration_date = self.held_option.ID.Date.date()

        if (expiration_date - self.Time.date()).days == 1:
            self.SubmitExit("expiration time stop")

    def ExpirationProcessing(self):
        self.no_entries_date = self.Time.date()

        if self.held_option is None:
            return

        expiration_date = self.held_option.ID.Date.date()

        if expiration_date <= self.Time.date():
            self.SubmitExit("expiration processing")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if (
            self.exit_ticket is not None
            and not self.exit_ticket.Status.IsClosed()
        ):
            return

        for order in self.Transactions.GetOpenOrders(self.held_option):
            self.CancelOrder(order.Id)

        quantity = self.Portfolio[self.held_option].Quantity

        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity
        )

        self.Debug(
            "Exit submitted (" + reason + "): "
            + str(self.held_option)
        )

    def UpdateTicketState(self):
        if (
            self.entry_ticket is not None
            and self.entry_ticket.Status.IsClosed()
        ):
            self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and self.exit_ticket.Status.IsClosed()
        ):
            self.exit_ticket = None

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment event")

            if self.Portfolio[self.spy].Invested:
                quantity = self.Portfolio[self.spy].Quantity
                self.MarketOrder(self.spy, -quantity)
                self.spy_liquidation_pending = True

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
            and order_event.FillQuantity > 0
        ):
            self.held_option = order_event.Symbol
            self.entry_fill_price = order_event.FillPrice
            self.profit_target = (
                self.entry_fill_price
                * (1 + self.PROFIT_TARGET_PCT)
            )

            self.Debug(
                "Entry filled: "
                + str(self.held_option)
                + " at "
                + str(self.entry_fill_price)
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: "
                + str(order_event.Symbol)
                + " at "
                + str(order_event.FillPrice)
            )

            self.held_option = None
            self.entry_fill_price = None
            self.profit_target = None

