from QuantConnect.Securities import OptionRight


class SpyFiveMinuteCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = {}

        self.held_option = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None

        self.no_entry_dates = set()

        # Configurable through a LEAN parameter; default is a 20% gain.
        target = self.GetParameter("ProfitTargetPercent")
        self.profit_target_percent = float(target) if target else 20.0

    def OnData(self, slice):
        self._handle_unexpected_spy_position()
        self._process_expiration()
        self._evaluate_option_exit(slice)

        if self.spy not in slice.Bars:
            return

        spy_bar = slice.Bars[self.spy]
        local_end = spy_bar.EndTime

        if local_end.tzinfo is not None:
            local_end = local_end.astimezone().replace(tzinfo=None)

        if not self._is_regular_session_five_minute_boundary(local_end):
            return

        if self.bucket_end is None:
            self.bucket_end = local_end
        elif local_end != self.bucket_end:
            self._finalize_bucket(slice)
            self.bucket_end = local_end
            self.bucket_bars = {}

        self.bucket_bars[local_end] = spy_bar

    def _is_regular_session_five_minute_boundary(self, end_time):
        if end_time.time() < time(9, 35) or end_time.time() > time(16, 0):
            return False
        return (
            end_time.second == 0
            and end_time.microsecond == 0
            and end_time.minute % 5 == 0
        )

    def _finalize_bucket(self, slice):
        if self.bucket_end is None:
            return

        expected_endings = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(end not in self.bucket_bars for end in expected_endings):
            return

        bars = [self.bucket_bars[end] for end in reversed(expected_endings)]

        consolidated = TradeBar(
            self.spy,
            bars[0].Time,
            self.bucket_end,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars)
        )

        close = consolidated.Close
        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if bullish_cross:
            eligible_start = time(9, 45)
            eligible_end = time(14, 30)

            if eligible_start <= self.bucket_end.time() <= eligible_end:
                self._try_enter(slice, close)

    def _try_enter(self, slice, spy_price):
        today = self.Time.date()

        if today in self.no_entry_dates:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        if self.spy_option not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        chain = slice.OptionChains[self.spy_option]
        minimum_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} expiration={} strike={}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

    def _evaluate_option_exit(self, slice):
        if self.held_option is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        expiry = self.held_option.ID.Date.date()
        today = self.Time.date()

        # Expiration processing begins on the expiration date.
        if today >= expiry:
            self.no_entry_dates.add(today)
            self._submit_exit("expiration processing")
            return

        previous_trading_day = self._previous_trading_day(expiry)
        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")
            return

        if self.held_option not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_option]
        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target_price = self.entry_price * (
            1.0 + self.profit_target_percent / 100.0
        )

        if midpoint >= target_price:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        for ticket in self.Transactions.GetOpenOrders(self.held_option):
            ticket.Cancel("Canceling competing exit order")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity > 0:
            self.exit_ticket = self.MarketOrder(
                self.held_option,
                -quantity
            )
            self.Debug(
                "Exit submitted: {} reason={}".format(
                    self.held_option, reason
                )
            )

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.entry_ticket.Symbol
                self.entry_price = self.entry_ticket.AverageFillPrice
                self.entry_ticket = None
                self.Debug(
                    "Entry filled: {} price={}".format(
                        self.held_option, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Entry order failed or was canceled.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(self.exit_ticket.Symbol))
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

    def _process_expiration(self):
        if self.held_option is None:
            return

        if self.Time.date() >= self.held_option.ID.Date.date():
            self.no_entry_dates.add(self.Time.date())
            self._submit_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.no_entry_dates.add(self.Time.date())
            self.Liquidate(self.spy, "Unexpected exercise or assignment")

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )
