            quantity = self.Portfolio[self.spy.Symbol].Quantity
            self.Debug("Unexpected SPY exercise/assignment; liquidating equity")
            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="unexpected assignment"
            )

        self.ExpirationCheck()
        self.ProfitTargetCheck(slice)

        if self.spy.Symbol not in slice.Bars:
            return

        completed = self.UpdateFiveMinuteBar(slice.Bars[self.spy.Symbol])
        if completed is None:
            return

        close, bar_end = completed

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
