        slow = sum(self.closes) / 20.0

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        if bullish_crossover:
            self.TryEnter(slice, close)

        self.previous_fast = fast
        self.previous_slow = slow

    def UpdateFiveMinuteBar(self, minute_bar):
        """
        Builds contiguous five-minute TradeBars aligned to New York clock
        boundaries: 09:30-09:35, 09:35-09:40, etc.
        """
        start = minute_bar.Time.replace(tzinfo=None)

        if start.time() < time(9, 30) or start.time() >= time(16, 0):
            return None

        if (
            self.bucket_start is None
            or start.date() != self.bucket_start.date()
        ):
            self.bucket_start = None
            self.bucket_bars = []

        if self.bucket_start is None:
            if start.minute % 5 != 0:
                return None

            self.bucket_start = start.replace(second=0, microsecond=0)
            self.bucket_bars = []

        expected = self.bucket_start + timedelta(
            minutes=len(self.bucket_bars)
        )

        if start != expected:
            self.bucket_start = None
            self.bucket_bars = []

            if start.minute % 5 != 0:
                return None

            self.bucket_start = start.replace(second=0, microsecond=0)

        self.bucket_bars.append(minute_bar)

        if len(self.bucket_bars) != 5:
            return None

        close = float(self.bucket_bars[-1].Close)
        bar_end = self.bucket_start + timedelta(minutes=5)

        self.closes.append(close)

        self.bucket_start = None
        self.bucket_bars = []

        if len(self.closes) < 20:
            return None

        return close, bar_end

    def TryEnter(self, slice: Slice, spy_price: float):
        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain in current Slice")
            return

        chain = slice.OptionChains[self.option_symbol]
        algorithm_date = self.Time.date()

        candidates = []

        for contract in chain:
            if contract.Right != OptionRight.Call:
                continue

            expiry_date = contract.Expiry.date()
            days_to_expiration = (expiry_date - algorithm_date).days

            if days_to_expiration >= 7:
                candidates.append(contract)

        if not candidates:
            self.Debug(
                "Skipped entry: no expiration at least seven calendar days out"
            )
            return

        selected_expiration = min(
            contract.Expiry.date() for contract in candidates
        )

        minimum_strike = 1.01 * float(spy_price)

        eligible = [
            contract
            for contract in candidates
            if contract.Expiry.date() == selected_expiration
            and float(contract.Strike) >= minimum_strike
        ]

        if not eligible:
            self.Debug(
                "Skipped entry: no eligible call at selected expiration"
            )
            return

        eligible.sort(
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        selected = eligible[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish crossover"
        )

        self.Debug("Entry submitted: " + str(selected.Symbol))

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
