from collections import deque
from datetime import datetime, date, time, timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):
    PROFIT_TARGET_PCT = 0.20

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol

        # Broad universe: weekly options, strikes around the underlying,
        # and expirations up to one year out.
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                      .Strikes(-100, 100)
                      .Expiration(0, 365)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)

        self._five_minute_date = None
        self._five_minute_bucket_end = None
        self._five_minute_bars = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.expiration_block_date = None
        self.assignment_liquidation_ticket = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing(current_date)
        self._evaluate_open_position_exit(slice, current_date)

        spy_bar = None
        if slice.Bars.ContainsKey(self.spy_symbol):
            spy_bar = slice.Bars[self.spy_symbol]

        if spy_bar is None:
            return

        signal_bar_end, bullish_crossover = self._update_five_minute_bar(spy_bar)

        if signal_bar_end is None or not bullish_crossover:
            return

        # Eligible crossover-bar close: 09:45 through 14:30 inclusive.
        bar_time = signal_bar_end.time()
        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        # Entry is evaluated exactly once for this completed bar.
        self._try_enter_from_current_chain(slice, current_date)

    def _update_five_minute_bar(self, minute_bar):
        end_time = minute_bar.EndTime
        if end_time.tzinfo is not None:
            end_time = end_time.replace(tzinfo=None)

        bar_date = end_time.date()
        end_clock = end_time.time()

        if end_clock < time(9, 31) or end_clock > time(16, 0):
            return None, False

        session_start = datetime.combine(bar_date, time(9, 30))
        minute_end = datetime.combine(bar_date, end_clock)

        bucket_index = int(
            (minute_end - datetime.combine(bar_date, time(9, 31))).total_seconds()
            // (5 * 60)
        )
        bucket_end = session_start + timedelta(minutes=5 * (bucket_index + 1))

        if self._five_minute_date != bar_date:
            self._five_minute_date = bar_date
            self._five_minute_bucket_end = None
            self._five_minute_bars = {}

        if (
            self._five_minute_bucket_end is not None
            and bucket_end != self._five_minute_bucket_end
        ):
            # Any unfinished prior bucket is discarded. No synthetic bar.
            self._five_minute_bars = {}

        self._five_minute_bucket_end = bucket_end
        self._five_minute_bars[end_time] = minute_bar

        expected_times = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if not all(t in self._five_minute_bars for t in expected_times):
            return None, False

        bars = [self._five_minute_bars[t] for t in expected_times]
        five_minute_close = bars[-1].Close

        previous_fast = None
        previous_slow = None

        if len(self.slow_closes) >= 20:
            previous_fast = sum(list(self.slow_closes)[-5:]) / 5.0
            previous_slow = sum(self.slow_closes) / 20.0

        self.fast_closes.append(five_minute_close)
        self.slow_closes.append(five_minute_close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            bullish = False
        else:
            current_fast = sum(self.fast_closes) / 5.0
            current_slow = sum(self.slow_closes) / 20.0

            bullish = (
                previous_fast is not None
                and previous_slow is not None
                and previous_fast <= previous_slow
                and current_fast > current_slow
            )

        self._five_minute_bars = {}
        return bucket_end, bullish

    def _try_enter_from_current_chain(self, slice: Slice, current_date: date):
        if self.expiration_block_date == current_date:
            return

        if self.entry_ticket is not None and not self._ticket_is_closed(self.entry_ticket):
            return

        if self._has_option_position():
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug("Skipped entry: current Slice has no SPY option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        if chain is None:
            self.Debug("Skipped entry: current Slice has no SPY option chain.")
            return

        spy_price = self.Securities[self.spy_symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: SPY price is unavailable or nonpositive.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies the seven-day rule.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no call at the selected expiration "
                "has a strike at least 1% out of the money."
            )
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"Entry submitted: {selected.Symbol.Value}, "
            f"expiration={selected.Expiry.date()}, strike={selected.Strike}"
        )

    def _evaluate_open_position_exit(self, slice: Slice, current_date: date):
        if self.entry_symbol is None or self.entry_price is None:
            return

        if not self.Portfolio.ContainsKey(self.entry_symbol):
            return

        holding = self.Portfolio[self.entry_symbol]
        if holding.Quantity <= 0:
            return

        expiry_date = self.Securities[self.entry_symbol].Symbol.ID.Date.date()

        # Time stop on the trading day immediately preceding expiration.
        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("time stop before expiration")
            return

        if not slice.QuoteBars.ContainsKey(self.entry_symbol):
            return

        quote = slice.QuoteBars[self.entry_symbol]
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target_price = self.entry_price * (1.0 + self.PROFIT_TARGET_PCT)

        if midpoint >= target_price:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.entry_symbol is None:
            return

        quantity = self.Portfolio[self.entry_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self._ticket_is_closed(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            f"Exit submitted: {self.entry_symbol.Value}, "
            f"quantity={quantity}, reason={reason}"
        )

    def _handle_expiration_processing(self, current_date):
        if self.entry_symbol is None:
            return

        expiry_date = self.Securities[self.entry_symbol].Symbol.ID.Date.date()

        if current_date < expiry_date:
            return

        self.expiration_block_date = current_date

        if self.entry_ticket is not None and not self._ticket_is_closed(self.entry_ticket):
            self.entry_ticket.Cancel("Expiration processing")

        if self._has_option_position():
            self._submit_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        spy_quantity = self.Portfolio[self.spy_symbol].Quantity
        if spy_quantity == 0:
            return

        if (
            self.assignment_liquidation_ticket is not None
            and not self._ticket_is_closed(self.assignment_liquidation_ticket)
        ):
            return

        self.Debug(
            f"Unexpected SPY equity position detected: "
            f"{spy_quantity}. Liquidating immediately."
        )

        self.assignment_liquidation_ticket = self.MarketOrder(
            self.spy_symbol,
            -spy_quantity,
            tag="Unexpected exercise or assignment"
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.entry_symbol.Value}, "
                    f"fill price={self.entry_price}"
                )

            if (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug(
                    f"Exit filled: {order_event.Symbol.Value}, "
                    f"fill price={order_event.FillPrice}"
                )
                self.exit_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if getattr(order_event, "IsAssignment", False) or \
           getattr(order_event, "IsExercise", False):
            self.Debug(
                f"Unexpected option exercise or assignment event: "
                f"{order_event.Symbol.Value}"
            )
            self._handle_unexpected_spy_position()

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Submitted
            )
            and self.entry_price is None
        ):
            if order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(
                    f"Entry order did not fill: {order_event.Status}"
                )
                self.entry_ticket = None
                self.entry_symbol = None

    def _has_option_position(self):
        return (
            self.entry_symbol is not None
            and self.Portfolio.ContainsKey(self.entry_symbol)
            and self.Portfolio[self.entry_symbol].Quantity > 0
        )

    def _ticket_is_closed(self, ticket):
        return ticket is None or ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _previous_trading_day(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        while not self.Securities[self.spy_symbol].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

