        self.previous_slow = None
        self.entry_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_fill_price = None
        self.time_stop_symbol = None
        self.expiration_block_date = None
        self.equity_liquidation_ticket = None

        # Configurable because the requested target percentage was unspecified.
        self.profit_target_percent = float(
            self.GetParameter("ProfitTargetPercent") or "0.20"
        )

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy.Symbol,
            self.consolidator
        )

    def OnData(self, slice: Slice):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()

        self.HandleHeldOptionExit(slice)

        # The consolidator callback runs while this Slice is being processed.
        # Entry selection therefore uses the current Slice's option chain.
        self.consolidator.Update(slice.Bars.get(self.spy.Symbol))

        if self.entry_signal:
            self.entry_signal = False
            self.TryEnter(slice)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        if bar.Symbol != self.spy.Symbol:
            return

        local_end = bar.EndTime.astimezone(
            self.TimeZone
        )

        # Regular-session bars only. With minute SPY data and a five-minute
        # consolidator, the first regular bar ends at 09:35 New York time.
        if local_end.date() != self.Time.date():
            return

        if local_end.time() < time(9, 35) or local_end.time() > time(16, 0):
            return

        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period:
            return

