        self.entry_price = None
        self.no_entries_today = False
        self.equity_cleanup_pending = False

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = {}
        self.processed_bucket = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.no_entries_today and self.Time.hour == 0 and self.Time.minute == 0:
            self.no_entries_today = False

        # Unexpected exercise or assignment handling.
        equity_holding = self.Portfolio[self.spy_symbol]
        if equity_holding.Invested:
            if not self.equity_cleanup_pending:
                self.Debug(
                    f"{self.Time}: Unexpected exercise/assignment created SPY "
                    f"equity; liquidating {equity_holding.Quantity} shares."
                )
                self.Liquidate(self.spy_symbol)
                self.equity_cleanup_pending = True
        else:
            self.equity_cleanup_pending = False

        held_symbol = self._held_option_symbol()

        # Never intentionally hold through expiration.
        if held_symbol is not None:
            expiration_date = held_symbol.ID.Date.date()

            if today >= expiration_date:
                self.no_entries_today = True
                self._liquidate_option(
                    held_symbol,
                    f"expiration processing for {expiration_date}"
                )
            else:
                previous_trading_day = self._previous_trading_day(expiration_date)

                if (
                    today == previous_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self._liquidate_option(
                        held_symbol,
                        f"time stop before expiration {expiration_date}"
                    )
                else:
                    self._evaluate_profit_target(slice, held_symbol)

        # Build five-minute bars from actual minute bars only.
        minute_bar = slice.Bars.get(self.spy_symbol)
        if minute_bar is not None:
            self._process_minute_bar(slice, minute_bar)

    def _process_minute_bar(self, slice: Slice, bar: TradeBar):
        bar_time = bar.Time
        bucket_end_minute = ((bar_time.minute // 5) + 1) * 5

        bucket_end = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            bar_time.hour,
            0,
            0
        ) + timedelta(minutes=bucket_end_minute)

        # Only regular-session bars are eligible.
        if bar_time.time() < datetime.strptime("09:30", "%H:%M").time():
            return
        if bar_time.time() >= datetime.strptime("16:00", "%H:%M").time():
            return

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self._complete_bucket(slice)

        if self.bucket_end is None:
            self.bucket_date = bar_time.date()
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        if bucket_end != self.bucket_end:
            return

        # Store only one actual minute bar per minute.
        self.bucket_bars[bar_time] = bar

        # A five-minute bar is valid only if all five minute bars exist.
        if len(self.bucket_bars) == 5 and self.processed_bucket != bucket_end:
            self._complete_bucket(slice)

    def _complete_bucket(self, slice: Slice):
