        if len(bars) == 5:
            ordered = [bars[t] for t in sorted(bars)]
            close = ordered[-1].Close

            self.closes.append(float(close))

            if len(self.closes) >= self.slow_period:
                fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
                slow = sum(self.closes) / self.slow_period

                bullish_cross = (
                    self.previous_fast is not None
                    and self.previous_slow is not None
                    and self.previous_fast <= self.previous_slow
                    and fast > slow
                )

                if (
                    bullish_cross
                    and datetime.strptime("09:45", "%H:%M").time()
                    <= bucket_end.time()
                    <= datetime.strptime("14:30", "%H:%M").time()
                ):
                    self._try_entry(slice, float(close), bucket_end)

                self.previous_fast = fast
                self.previous_slow = slow

        self.processed_bucket = bucket_end
        self.bucket_end = None
        self.bucket_date = None
        self.bucket_bars = {}

