        if self._held_option_symbol() is not None:
            return

        if self.entry_ticket is not None and not self._order_finished(
            self.entry_ticket
        ):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{bar_end}: Entry skipped; no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        contracts = list(chain)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug(f"{bar_end}: Entry skipped; no valid expiration.")
            return

        expiration = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{bar_end}: Entry skipped; no call strike meets "
                f"{minimum_strike:.2f}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"{bar_end}: Submitted market entry for {selected.Symbol}; "
            f"expiration {expiration}, strike {selected.Strike}."
        )

    def _evaluate_profit_target(self, slice: Slice, symbol: Symbol):
        if self.entry_price is None:
            return

        quote = slice.QuoteBars.get(symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_price * (1.0 + self.profit_target_percent)

        if midpoint >= target:
            self._cancel_exit_order()
            self._liquidate_option(symbol, "profit target")

    def _liquidate_option(self, symbol: Symbol, reason: str):
        holding = self.Portfolio[symbol]
        quantity = holding.Quantity

        if quantity == 0:
            return

        self._cancel_exit_order()

        if self.exit_ticket is None or self._order_finished(self.exit_ticket):
            self.exit_ticket = self.MarketOrder(symbol, -quantity)
            self.Debug(
                f"{self.Time}: Submitted market exit for {symbol}; reason: {reason}."
            )

    def _held_option_symbol(self):
        if self.entry_symbol is None:
            return None

        holding = self.Portfolio[self.entry_symbol]
        return self.entry_symbol if holding.Invested else None

    def _cancel_exit_order(self):
        if self.exit_ticket is not None and not self._order_finished(
            self.exit_ticket
        ):
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

    def _order_finished(self, ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None_,
            OrderStatus.CancelPending
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy_symbol].Exchange.Hours

        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)

        try:
            while not exchange_hours.IsDateOpen(
                datetime(candidate.year, candidate.month, candidate.day)
            ):
                candidate -= timedelta(days=1)
        except Exception:
            pass

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled for {self.entry_symbol} "
                    f"at {self.entry_price:.4f}."
                )

            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                f"{self.Time}: Exit filled for {order_event.Symbol} "
                f"at {order_event.FillPrice:.4f}."
            )
            self.exit_ticket = None
            self.entry_ticket = None
            self.entry_symbol = None
