from AlgorithmImports import *
from collections import defaultdict
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    # Assumption because the requested threshold was not specified.
    PROFIT_TARGET_MULTIPLE = 1.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-500, 500)
                       .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast_values = []
        self.slow_values = []
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bars = defaultdict(dict)
        self.held_symbol = None
        self.entry_price = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.expiration_guard_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # Prevent replacement entries on the day expiration processing begins.
        if self.held_symbol is not None:
            expiry = self._held_expiry()
            if expiry is not None and current_date >= expiry:
                if self.expiration_guard_date != current_date:
                    self.expiration_guard_date = current_date
                    self.Debug(
                        "Expiration processing: liquidating held option."
                    )
                    self._submit_exit("expiration processing")

        # Immediately liquidate unexpected SPY equity created by exercise/assignment.
        spy_quantity = self.Portfolio[self.spy].Quantity
        if spy_quantity != 0:
            self.Debug(
                "Unexpected exercise/assignment handling: liquidating SPY equity."
            )
            self.Liquidate(self.spy, "unexpected exercise or assignment")

        # Evaluate exits on every minute Slice.
        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Invested:
            expiry = self._held_expiry()

            if expiry is not None:
                previous_trading_day = self._previous_trading_day(expiry)
                if (
                    current_date == previous_trading_day
                    and self.Time.time() >= time(15, 45)
                ):
                    self._submit_exit("pre-expiration time stop")
                else:
                    self._evaluate_profit_target(slice)

        # Build five-minute bars from actual minute bars only.
        completed_bar = self._update_five_minute_bar(slice)
        if completed_bar is not None:
            self._evaluate_crossover_entry(slice, completed_bar)

    def _update_five_minute_bar(self, slice: Slice):
        if not slice.Bars.ContainsKey(self.spy):
            return None

        bar = slice.Bars[self.spy]
        bar_time = bar.Time
        date = bar_time.date()

        if bar_time.time() < time(9, 30) or bar_time.time() >= time(16, 0):
            return None

        minutes_from_open = (
            bar_time.hour * 60 + bar_time.minute
            - (9 * 60 + 30)
        )
        bucket_minute = 9 * 60 + 30 + (minutes_from_open // 5) * 5
        bucket_start = datetime(
            date.year,
            date.month,
            date.day,
            bucket_minute // 60,
            bucket_minute % 60
        )

        bucket = self.minute_bars[bucket_start]
        bucket[bar_time] = bar

        # A five-minute bar completes as soon as its fifth actual minute arrives.
        expected_times = [
            bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if all(t in bucket for t in expected_times):
            bars = [bucket[t] for t in expected_times]
            del self.minute_bars[bucket_start]

            return {
                "end": bucket_start + timedelta(minutes=5),
                "close": bars[-1].Close
            }

        # If a later minute arrives in a new bucket, discard incomplete buckets.
        stale = [
            key for key in self.minute_bars
            if key < bucket_start - timedelta(minutes=5)
        ]
        for key in stale:
            del self.minute_bars[key]

        return None

    def _evaluate_crossover_entry(self, slice: Slice, five_minute_bar):
        bar_end = five_minute_bar["end"]
        close = five_minute_bar["close"]

        self.fast_values.append(close)
        self.slow_values.append(close)

        if len(self.fast_values) > 5:
            self.fast_values.pop(0)
        if len(self.slow_values) > 20:
            self.slow_values.pop(0)

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            return

        fast = sum(self.fast_values[-5:]) / 5.0
        slow = sum(self.slow_values[-20:]) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        if not bullish:
            return

        if not (time(9, 45) <= bar_end.time() <= time(14, 30)):
            return

        if self.expiration_guard_date == self.Time.date():
            return

        if self.entry_order_id is not None:
            return

        if self._has_option_holding():
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration satisfies minimum DTE.")
            return

        selected_expiry = expirations[0]
        spy_price = self.Securities[self.spy].Price
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at selected expiration."
            )
            return

        candidates.sort(key=lambda c: (c.Strike, str(c.Symbol)))
        selected = candidates[0]

        ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="bullish five-minute crossover entry"
        )

        self.entry_order_id = ticket.OrderId
        self.held_symbol = selected.Symbol

        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.entry_price is None:
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = None
        for candidate in chain:
            if candidate.Symbol == self.held_symbol:
                contract = candidate
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * self.PROFIT_TARGET_MULTIPLE:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_order_id is not None:
            self.Transactions.CancelOrder(
                self.exit_order_id,
                "cancelled before replacement exit"
            )
            self.exit_order_id = None

        ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted: {0}".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.entry_order_id = None
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Entry order did not fill.")
                self.entry_order_id = None
                self.held_symbol = None

        if order_event.OrderId == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {0} at {1}".format(
                        self.held_symbol,
                        order_event.FillPrice
                    )
                )
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_order_id = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                "Unexpected assignment event: liquidating resulting SPY position."
            )
            if self.Portfolio[self.spy].Quantity != 0:
                self.Liquidate(self.spy, "assignment handling")

    def _has_option_holding(self):
        for security in self.Portfolio.Values:
            if (
                security.Type == SecurityType.Option
                and security.Quantity != 0
            ):
                return True
        return False

    def _held_expiry(self):
        if self.held_symbol is None:
            return None

        security = self.Securities.get(self.held_symbol)
        if security is None:
            return None

        return security.Symbol.ID.Date.date()

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
