    def AcceptMinuteBar(self, bar: TradeBar):
        end = bar.EndTime
        t = end.time()

        if end.weekday() >= 5:
            return

        if t <= datetime(2000, 1, 1, 9, 30).time():
            return

        if t > datetime(2000, 1, 1, 16, 0).time():
            return

        minutes = (t.hour * 60 + t.minute) - (9 * 60 + 30)
        bucket_number = int(math.ceil(minutes / 5.0))

        bucket_end = datetime.combine(
            end.date(),
            datetime.min.time()
        ) + timedelta(minutes=570 + bucket_number * 5)

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self.CompleteBucket()
            self.bucket_bars = {}

        self.bucket_end = bucket_end
        self.bucket_bars[end] = bar

        if end == bucket_end:
            self.CompleteBucket()
            self.bucket_bars = {}
            self.bucket_end = None

    def CompleteBucket(self):
        if self.bucket_end is None or len(self.bucket_bars) != 5:
            return

        expected = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(t not in self.bucket_bars for t in expected):
            return

        bars = [self.bucket_bars[t] for t in expected]

        consolidated = TradeBar(
            bars[0].Time,
            self.spy,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )

        self.OnFiveMinuteBar(consolidated)

    def OnFiveMinuteBar(self, bar: TradeBar):
        prior_fast = (
            sum(self.fast) / 5
            if len(self.fast) == 5 else None
        )
        prior_slow = (
            sum(self.slow) / 20
            if len(self.slow) == 20 else None
        )

        self.fast.append(float(bar.Close))
        self.slow.append(float(bar.Close))

        current_fast = (
            sum(self.fast) / 5
            if len(self.fast) == 5 else None
        )
        current_slow = (
            sum(self.slow) / 20
            if len(self.slow) == 20 else None
        )

        bullish_cross = (
            prior_fast is not None and
            prior_slow is not None and
            current_fast is not None and
            current_slow is not None and
            prior_fast <= prior_slow and
            current_fast > current_slow
        )

        t = bar.EndTime.time()
        eligible = (
            datetime(2000, 1, 1, 9, 45).time() <= t <=
            datetime(2000, 1, 1, 14, 30).time()
        )

        if eligible and bullish_cross:
            self.TryEnter(float(bar.Close))

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def TryEnter(self, spy_price):
        if self.held_symbol is not None or self.EntryOpen():
            return

