from AlgorithmImports import *

from collections import deque
from datetime import datetime, timedelta
import math


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    # The requested target percentage was unspecified.
    PROFIT_TARGET_PCT = 0.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False,
            leverage=1
        ).Symbol

        self.option = self.AddOption(
            "SPY",
            Resolution.Minute,
            Market.USA,
            fillForward=False
        ).Symbol

        self.Securities[self.option].SetFilter(
            lambda u: u.IncludeWeeklys()
                       .Strikes(-200, 200)
                       .Expiration(0, 370)
        )

        self.fast = deque(maxlen=5)
        self.slow = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_bars = {}

        self.current_chain = None
        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.blocked_dates = set()

    def OnData(self, slice: Slice):
        self.current_chain = None

        try:
            if self.option in slice.OptionChains:
                self.current_chain = slice.OptionChains[self.option]
        except Exception:
            pass

        self.HandleUnexpectedEquityPosition()
        self.HandleExpiration()
        self.EvaluateExit(slice)

        if self.spy in slice.Bars:
            self.AcceptMinuteBar(slice.Bars[self.spy])

    def AcceptMinuteBar(self, bar: TradeBar):
        end = bar.EndTime
        t = end.time()

        if end.weekday() >= 5:
            return

        if t <= datetime(2000, 1, 1, 9, 30).time():
            return

        if t > datetime(2000, 1, 1, 16, 0).time():
            return

        minutes = (t.hour * 60 + t.minute) - (9 * 60 + 30)
        bucket_number = int(math.ceil(minutes / 5.0))

        bucket_end = datetime.combine(
            end.date(),
            datetime.min.time()
        ) + timedelta(minutes=570 + bucket_number * 5)

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self.CompleteBucket()
            self.bucket_bars = {}

        self.bucket_end = bucket_end
        self.bucket_bars[end] = bar

        if end == bucket_end:
            self.CompleteBucket()
            self.bucket_bars = {}
            self.bucket_end = None

    def CompleteBucket(self):
        if self.bucket_end is None or len(self.bucket_bars) != 5:
            return

        expected = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(t not in self.bucket_bars for t in expected):
            return

        bars = [self.bucket_bars[t] for t in expected]

        consolidated = TradeBar(
            bars[0].Time,
            self.spy,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )

        self.OnFiveMinuteBar(consolidated)

    def OnFiveMinuteBar(self, bar: TradeBar):
        prior_fast = (
            sum(self.fast) / 5
            if len(self.fast) == 5 else None
        )
        prior_slow = (
            sum(self.slow) / 20
            if len(self.slow) == 20 else None
        )

        self.fast.append(float(bar.Close))
        self.slow.append(float(bar.Close))

        current_fast = (
            sum(self.fast) / 5
            if len(self.fast) == 5 else None
        )
        current_slow = (
            sum(self.slow) / 20
            if len(self.slow) == 20 else None
        )

        bullish_cross = (
            prior_fast is not None and
            prior_slow is not None and
            current_fast is not None and
            current_slow is not None and
            prior_fast <= prior_slow and
            current_fast > current_slow
        )

        t = bar.EndTime.time()
        eligible = (
            datetime(2000, 1, 1, 9, 45).time() <= t <=
            datetime(2000, 1, 1, 14, 30).time()
        )

        if eligible and bullish_cross:
            self.TryEnter(float(bar.Close))

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def TryEnter(self, spy_price):
        if self.held_symbol is not None or self.EntryOpen():
            return

        if self.Time.date() in self.blocked_dates:
            return

        if self.current_chain is None:
            self.Debug("Skipped entry: no option chain")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in self.current_chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no qualifying expiration")
            return

        expiry = expiries[0]

        contracts = [
            contract
            for contract in self.current_chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= 1.01 * spy_price
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying call strike")
            return

        selected = min(
            contracts,
            key=lambda c: (float(c.Strike), str(c.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish crossover entry"
        )

        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def EvaluateExit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if quantity <= 0 or self.ExitOpen():
            return

        expiry = self.held_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry:
            self.SubmitExit("expiration processing")
            self.blocked_dates.add(today)
            return

        if (
            self.Time.time() >= datetime(2000, 1, 1, 15, 45).time()
            and today == self.PreviousTradingDay(expiry)
        ):
            self.SubmitExit("pre-expiration time stop")
            return

        try:
            if self.held_symbol not in slice.QuoteBars:
                return

            quote = slice.QuoteBars[self.held_symbol]
            bid = float(quote.Bid.Close)
            ask = float(quote.Ask.Close)

            if bid <= 0 or ask <= 0:
                return

            midpoint = (bid + ask) / 2.0
            target = self.entry_price * (1.0 + self.PROFIT_TARGET_PCT)

            if midpoint >= target:
                self.SubmitExit("profit target")

        except Exception:
            return

    def SubmitExit(self, reason):
        if self.held_symbol is None or self.ExitOpen():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity

        if self.EntryOpen():
            self.entry_ticket.Cancel("Exit requested before entry fill")

        if quantity > 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                -quantity,
                tag=reason
            )
            self.Debug(
                "Exit submitted ({}): {}".format(reason, self.held_symbol)
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            getattr(order_event, "IsAssignment", False)
            or getattr(order_event, "IsExercise", False)
        ):
            self.Debug(
                "Unexpected exercise/assignment: {}".format(
                    order_event.Message
                )
            )

            quantity = self.Portfolio[self.spy].Quantity

            if quantity != 0:
                self.MarketOrder(
                    self.spy,
                    -quantity,
                    tag="Exercise/assignment cleanup"
                )

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.held_symbol = self.entry_ticket.Symbol

                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {} at {:.4f}".format(
                    self.held_symbol,
                    order_event.FillPrice
                )
            )

            self.held_symbol = None
            self.entry_price = None
            self.entry_ticket = None
            self.exit_ticket = None

    def EntryOpen(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def ExitOpen(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def HandleExpiration(self):
        if (
            self.held_symbol is not None
            and self.Time.date() >= self.held_symbol.ID.Date.date()
        ):
            self.blocked_dates.add(self.Time.date())

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected SPY equity position; liquidating immediately"
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected equity cleanup"
            )

    def PreviousTradingDay(self, expiry):
        day = expiry - timedelta(days=1)

        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(day.year, day.month, day.day)
        ):
