            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol),
            ),
        )[0]

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="MA crossover call entry",
        )

        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _process_position(self, slice: Slice):
        symbol = self.entry_symbol
        expiry = symbol.ID.Date.date()
        today = self.Time.date()
        quantity = self.Portfolio[symbol].Quantity

        if today >= expiry:
            self.no_entry_dates.add(today)

            if quantity != 0 and self._no_open_exit():
                self.exit_ticket = self.MarketOrder(
                    symbol,
                    -quantity,
                    tag="expiration liquidation",
                )
                self.Debug(
                    "Exit submitted: expiration liquidation for {}".format(
                        symbol
                    )
                )
            return

        if (
            today == expiry - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
        ):
            if quantity != 0 and self._no_open_exit():
                self.exit_ticket = self.MarketOrder(
                    symbol,
                    -quantity,
                    tag="pre-expiration time stop",
                )
                self.Debug(
                    "Exit submitted: pre-expiration time stop for {}".format(
                        symbol
                    )
                )
            return

        if (
            quantity == 0
            or self.entry_price is None
            or not self._no_open_exit()
        ):
            return

        quote = self._quote_from_slice(slice, symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        target = self.entry_price * (
            1.0 + self.profit_target_percent / 100.0
        )

        if midpoint >= target:
            self._cancel_open_exit()
            self.exit_ticket = self.MarketOrder(
                symbol,
                -quantity,
                tag="profit target",
            )
            self.Debug(
                "Exit submitted: profit target for {}".format(symbol)
            )

    def _quote_from_slice(self, slice: Slice, symbol):
        chain = (
            slice.OptionChains.get(self.option)
            if slice.OptionChains
            else None
        )

        if chain is not None:
            for contract in chain:
                if contract.Symbol == symbol:
                    return (
                        float(contract.BidPrice),
                        float(contract.AskPrice),
                    )

        quote = slice.QuoteBars.get(symbol) if slice.QuoteBars else None
        if quote is not None and quote.Bid is not None and quote.Ask is not None:
            return (
                float(quote.Bid.Close),
                float(quote.Ask.Close),
            )

        return None

    def _no_open_exit(self):
        return (
            self.exit_ticket is None
            or self.exit_ticket.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            )
        )

    def _cancel_open_exit(self):
        if not self._no_open_exit():
            self.exit_ticket.Cancel("Replaced by profit-target exit")

    def _liquidate_unexpected_spy(self, reason):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            self.Debug(
                "Unexpected exercise/assignment handling: {}".format(reason)
            )
            self.MarketOrder(
                self.spy,
                -quantity,
                tag="unexpected SPY liquidation",
            )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity != 0:
                self.entry_price = float(order_event.FillPrice)

            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.entry_symbol,
                        self.entry_price,
                    )
                )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exit filled: {}".format(self.entry_symbol))
            self.entry_ticket = None
            self.entry_symbol = None
            self.entry_price = None
            self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self._liquidate_unexpected_spy("assignment event")

    def OnEndOfAlgorithm(self):
        if (
            self.entry_symbol is not None
            and self.Portfolio[self.entry_symbol].Quantity != 0
        ):
            self.Debug(
                "Unexpected option holding at algorithm end: {}".format(
                    self.entry_symbol
                )
            )
