            self.expiration_processing_date = today
            self.no_entry_date = today

            if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
                self.entry_ticket.Cancel("Cancelling entry on expiration processing.")

            if self.Portfolio[self.held_symbol].Invested:
                self._submit_exit("expiration processing")

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]

        if holding.Quantity != 0:
            self.no_entry_date = self.Time.date()
            self.Debug(
                f"Unexpected SPY equity position detected, quantity={holding.Quantity}; "
                "liquidating immediately."
            )
            self.MarketOrder(self.spy, -holding.Quantity, tag="unexpected exercise/assignment")

    def _previous_trading_day(self, calendar_date):
        candidate = calendar_date - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _order_is_open(self, ticket):
        return ticket is not None and ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ]

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        f"Entry filled: {self.held_symbol}; "
                        f"price={self.entry_price}"
                    )

                elif order_event.Status in [
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ]:
                    self.Debug(
                        f"Entry order not filled: {order_event.Status}"
                    )
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol}; "
                        f"price={order_event.FillPrice}"
                    )

                    if not self.Portfolio[order_event.Symbol].Invested:
                        self.held_symbol = None
                        self.entry_price = None
                        self.exit_ticket = None

                elif order_event.Status in [
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ]:
                    self.exit_ticket = None

        if order_event.Symbol == self.spy:
            self._handle_unexpected_spy_position()
